INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65804673', 65804673, 'analyze_legacy', 'Kab. Pesawaran', 'kabkota', 'Badan Penelitian dan Pengembangan Daerah', 'Belanja Sewa Kendaraan Dinas Bermotor Perorangan', 'Jasa Lainnya', 'E-Purchasing', 'Lampung, Pesawaran (Kab.)', 212000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Sewa Kendaraan Dinas Bermotor Perorangan; Kendaraan Dinas Operasional Sewa (KDOS);', 'Mobil MPV transmisi CVT V 2.0 HV dan 7 kursi,; Mobil SUV S 1.5 GR-S A/T;', 212000000, 'absurd', 'Pengadaan sewa kendaraan dinas perorangan dengan spesifikasi MPV hybrid 2.0 dan SUV varian GR-S mengarah pada penggunaan kendaraan berfitur/trim relatif premium untuk kebutuhan birokrasi. Untuk perangkat daerah penelitian dan pengembangan, pilihan spesifikasi seperti ini menimbulkan kesan kemewahan dan kurang hemat, sehingga seluruh nilai patut dicermati sebagai potensi pemborosan.', NULL, NULL, 4, 1, 1, 1, 1, 2381810);
