INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65853375', 65853375, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Penyusunan Matek Revisi RTR KSN Kawasan Perkotaan Cekungan Bandung', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 4211388000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '1', 'The objective of this work consists of 3 (three) components as follows. 1. To prepare the review study of the Presidential Regulation Number 45 of 2018 on RTR KSN Cekungan Bandung Metropolitan Area as a basis for policy development and operationalization of spatial utilization. 2. To prepare the Technical Material and draft revision of Presidential Regulation on RTR KSN Cekungan Bandung as a basis for policy development and operational implementation of spatial utilization; and 3. To prepare the Strategic Environmental Assessment (KLHS) document of the RTR KSN Cekungan Bandung', 'To achieve those objectives and targets, 8 (eight) tasks need to be carried out. All of these tasks are interrelated, as their respective outputs serve as inputs for the subsequent tasks. Therefore, the Consulting Service Provider is required to understand the workflow in accordance with the applicable laws and regulations, as well as technical guidelines related to the review, preparation of technical material documents, 5 the Draft of Presidential Regulation along with the preparation of Strategic Environmental Assessment document, and the associated KLHS. All the tasks must be carried out in compliance with ILASP Environmental and Social Management Framework (ESMF). The tasks are as follows: 1. Task 1: Preparation 2. Task 2: Review Study of Presidential Regulation No. 45/2018 on the Spatial Plan of the Cekungan Bandung Metropolitan Area 3. Task 3: Data and Information Collection, Processing, and Analysis 4. Task 4: Formulation of Key Performance Indicators (KPI) 5. Task 5: Formulation of Spatial Planning Concept 6. Task 6: Preparation of KLHS Document 7. Task 7: Preparation of the Draft of Presidential Regulation on Spatial Plan of National Strategic Area (RTR KSN) 8. Task 8: Preparation of Reporting Documents', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2385679);
